def allocate_lane_trade_id(research_lane: str) -> str:
    """Stable lane-prefixed trade_id — relay + CSV must never see bare UUIDs."""
    lane = str(research_lane or RESEARCH_LANE_AI_SCAN).upper()
    if lane == RESEARCH_LANE_CONTINUOUS:
        prefix = "cont"
    elif is_ai_scan_lane(lane):
        prefix = "scan"
    else:
        prefix = (
            COMBO_LANE_SPECS.get(lane, {}).get("id_prefix")
            or _SPAWN_LANE_ID_PREFIX.get(lane)
            or "lane"
        )
    return f"{prefix}-{uuid.uuid4().hex[:12]}"


def relay_publishes_approve_outcome(research_lane: str) -> bool:
    """AI_SCAN routes to spawn lanes only — must not overwrite relay-facing approve snapshot."""
    return not is_ai_scan_lane(str(research_lane or "").upper())


SHADOW_RUNNER_HORIZON_SECS = {
    "15m": 900,
    "30m": 1800,
    "60m": 3600,
    "90m": 5400,
}


def _spawn_ai_prob_ge(ai, lo: int) -> bool:
    try:
        return int(ai.get("win_prob") or 0) >= int(lo)
    except (TypeError, ValueError):
        return False


def _spawn_structure_score(ctx, features=None) -> float:
    mc = ctx or {}
    ms = mc.get("market_structure") or {}
    if ms.get("structure_score") is None and isinstance(features, dict):
        ms = features.get("market_structure") or ms
    try:
        return float(ms.get("structure_score") or mc.get("structure_score") or 0)
    except (TypeError, ValueError):
        return 0.0


def _spawn_near_support(ctx, features) -> bool:
    sr = (
        (features or {}).get("sr_state")
        or (ctx or {}).get("sr_state")
        or (state.get("support_resistance") or {}).get("sr_state")
    )
    return _sr_location_bucket(sr) == "NEAR_SUPPORT"


def _spawn_ai_prob_in_band(ai, lo: int = 50, hi: int = 55) -> bool:
    try:
        prob = int(ai.get("win_prob") or 0)
    except (TypeError, ValueError):
        return False
    return lo <= prob <= hi


def compute_binance_fee_stress(trades: list) -> dict:
    """Reference PnL after Binance USDT-M VIP0 taker round-trip (not live exchange)."""
    lev = int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE))
    margin = float(FIXED_MARGIN_USDT)
    notional = margin * lev
    fee_per_trade = round(notional * BINANCE_USDT_M_TAKER_FEE * 2, 4)
    lanes_out = {}
    for lane_key, lane_label in RESEARCH_LANE_LABELS.items():
        if lane_key == RESEARCH_LANE_PROFIT_GATES:
            continue
        lt = [t for t in (trades or []) if str(t.get("research_lane") or "") == lane_key]
        n = len(lt)
        gross = round(sum(float(t.get("net_pnl_usd") or t.get("net") or 0) for t in lt), 2)
        fees = round(n * fee_per_trade, 2)
        net = round(gross - fees, 2)
        lanes_out[lane_key] = {
            "label": lane_label,
            "trades": n,
            "gross_pnl_usd": gross,
            "est_fees_usd": fees,
            "net_after_fees_usd": net,
            "profitable": net > 0,
            "fee_per_trade_usd": fee_per_trade,
        }
    return {
        "exchange": "binance_usdt_m",
        "fee_model": "VIP0 taker 0.05% entry + 0.05% exit (reference)",
        "maker_fee_pct": BINANCE_USDT_M_MAKER_FEE * 100,
        "taker_fee_pct": BINANCE_USDT_M_TAKER_FEE * 100,
        "margin_usd": margin,
        "leverage": lev,
        "notional_usd": round(notional, 2),
        "fee_per_round_trip_usd": fee_per_trade,
        "lanes": lanes_out,
    }


def _golden_stack_pass_for_spawn(final_direction, ctx, ai, features, edge_score, signal_stub=None) -> tuple:
    probe = signal_stub or {
        "final_direction": final_direction,
        "signal_price": nz(state.get("price")),
        "trade_id": f"gs-probe-{uuid.uuid4().hex[:8]}",
        "features": features or {},
        "context": ctx,
        "trade_planner": copy.deepcopy((ai or {}).get("trade_planner") or {}),
    }
    if not probe.get("entry_mode"):
        compute_continuous_ai_direct_entry(probe)
    blocked, reason = evaluate_golden_stack_filter(
        final_direction, ctx, ai, features, edge_score, probe,
    )
    return not blocked, reason


