def _trade_row_in_session(trade: dict, session_start: float) -> bool:
    if not session_start:
        return True
    ts = parse_ts(trade.get("ts") or "")
    if ts >= session_start - 1.0:
        return True
    try:
        entry_ts = float(trade.get("entry_ts") or 0)
        if entry_ts >= session_start - 1.0:
            return True
    except (ValueError, TypeError):
        pass
    return False

def _showcase_trade_session_start() -> float:
    """Epoch for trade filtering: full CSV history unless fresh-collection mode is on."""
    if not state.get("fresh_collection_mode", False):
        return 0.0
    return float(bot_start_time or 0.0)

def _recompute_research_balance_from_trades():
    """Restore RESEARCH showcase balance from persisted trades after restart/upgrade."""
    if state.get("strategy_mode") != "RESEARCH" or state.get("live_armed"):
        return
    session_start = _showcase_trade_session_start()
    with trade_lock:
        rows = list(trades)
    if not rows:
        with state_lock:
            state["account_balance"] = STARTING_BALANCE
        return
    total_pnl = 0.0
    counted = 0
    for t in rows:
        if session_start and not _trade_row_in_session(t, session_start):
            continue
        try:
            pnl = float(t.get("net_pnl_usd") or t.get("pnl") or 0.0)
        except (ValueError, TypeError):
            pnl = 0.0
        total_pnl += pnl
        counted += 1
    restored = round(STARTING_BALANCE + total_pnl, 4)
    with state_lock:
        state["account_balance"] = restored
    logger.info(
        f"[STARTUP] Restored showcase balance={restored} from {counted} trade(s) "
        f"fresh_collection={bool(state.get('fresh_collection_mode', False))} [PIPELINE ENFORCEMENT]"
    )

def load_session_trades_from_csv():
    """Load closed trades from CSV for the current analysis window into in-memory trades list."""
    session_start = _research_data_start_ts()
    if not session_start or not os.path.exists(CSV_TRADES):
        return 0
    existing_ids = {t.get("trade_id") for t in trades if t.get("trade_id")}
    loaded = 0
    float_fields = (
        "entry", "exit", "dur_min", "pnl", "net_pnl_usd", "gross_pnl_usd",
        "trading_fees_usd", "fees_usd", "funding_fees_usd", "entry_ts",
    )
    try:
        with open(CSV_TRADES, "r", encoding="utf-8", errors="replace") as f:
            for row in csv.DictReader(f):
                tid = row.get("trade_id")
                if not tid or tid in existing_ids:
                    continue
                if not _trade_row_in_session(row, session_start):
                    continue
                trade = dict(row)
                for k in float_fields:
                    if trade.get(k) not in (None, ""):
                        try:
                            trade[k] = float(trade[k])
                        except (ValueError, TypeError):
                            pass
                trades.append(trade)
                existing_ids.add(tid)
                loaded += 1
    except Exception as e:
        logger.warning(f"[STARTUP] load_session_trades_from_csv failed: {e} [PIPELINE ENFORCEMENT]")
        return 0
    if loaded:
        logger.info(f"[STARTUP] Loaded {loaded} session trade(s) from {CSV_TRADES} [PIPELINE ENFORCEMENT]")
    return loaded

