_DASHBOARD_TRADE_API_KEYS = (
    "ts", "ts_melbourne", "trade_id", "research_lane", "research_model",
    "final_direction", "dir", "entry", "exit", "dur_min", "pnl",
    "net_pnl_usd", "gross_pnl_usd", "trading_fees_usd", "fees_usd",
    "funding_fees_usd", "ai_band", "exit_reason", "close_ts_melbourne",
)


def _slim_trade_for_dashboard(trade: dict) -> dict:
    """Dashboard trades table only needs a small column subset — full CSV rows are megabytes."""
    if not isinstance(trade, dict):
        return trade
    row = _enrich_melbourne_time_fields(trade)
    return {k: row.get(k) for k in _DASHBOARD_TRADE_API_KEYS if row.get(k) not in (None, "")}


def _session_trade_count() -> int:
    """Count session trades for dashboard totals without copying rows."""
    session_start = _showcase_trade_session_start()
    with trade_lock:
        if not session_start:
            return len(trades)
        return sum(1 for t in trades if _trade_row_in_session(t, session_start))


def _snapshot_trades_for_api(session_start: float):
    """Session-filtered trade rows for /api/state — cap size so dashboard polls stay fast."""
    if session_start:
        src = [t for t in trades if _trade_row_in_session(t, session_start)]
    else:
        src = list(trades)
    if len(src) > _DASHBOARD_TRADES_MAX:
        src = src[-_DASHBOARD_TRADES_MAX:]
    return list(src)


@app.route('/api/state')
def api_state():
    t0 = time.perf_counter()
    now_wall = time.time()
    with _api_state_cache_lock:
        cached = _api_state_cache.get("payload")
        if cached is not None and now_wall - _api_state_cache["built_at"] < _API_STATE_CACHE_TTL_SEC:
            resp = jsonify(cached)
            resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
            resp.headers["Pragma"] = "no-cache"
            resp.headers["X-Api-State-Cache"] = "hit"
            return resp
        if _api_state_cache.get("building"):
            return ("", 204)
        _api_state_cache["building"] = True
    try:
        # Never block HTTP on Bitfinex REST here — state_monitor_loop refreshes price/funding in background.
        # Lock order: state_lock before trade_lock (close_position may take trade_lock after state work).
        now_ts = time.time()
        session_start = _showcase_trade_session_start()
        with state_lock:
            snapshot = copy.deepcopy(state)
            snapshot.pop("order_book", None)
            ai_hist_src = state.get("ai_history") or []
            ai_history_total = len(ai_hist_src)
            ai_history_copy = [dict(r) for r in ai_hist_src[-_DASHBOARD_HISTORY_MAX:]]
        with trade_lock:
            trades_copy = _snapshot_trades_for_api(session_start)
            expired_orders_total = len(expired_orders)
            expired_orders_copy = copy.deepcopy(expired_orders[-_DASHBOARD_HISTORY_MAX:])
            for pos in open_positions:
                if pos.get("status") == "OPEN":
                    accrue_position_funding(pos, now_ts)
            positions_copy = copy.deepcopy(open_positions)
            pending_orders_copy = copy.deepcopy(pending_orders)
            active_list, exposure_count = _collect_dashboard_active_signals(
                pending_orders_copy,
                positions_copy,
                trades_map,
                default_strategy=snapshot.get("strategy", "-"),
                default_regime=snapshot.get("regime", "-"),
            )
            pending_by_tid = {o.get("trade_id"): o for o in pending_orders_copy if o.get("trade_id")}
            for sig in active_list:
                tid = sig.get("trade_id")
                if tid and not sig.get("fill_price"):
                    po = pending_by_tid.get(tid) or {}
                    sig["fill_price"] = po.get("fill_price") or po.get("limit_price") or sig.get("limit_price")
            lane_position_counts = {
                ln: {
                    "open": len(lane_open_positions.get(ln, [])),
                    "pending": len(lane_pending_orders.get(ln, [])),
                }
                for ln in PATHWAY_LAB_LANES
            }
        expired_orders_copy = [_expired_order_api_row(e) for e in expired_orders_copy if isinstance(e, dict)]
        ai_history_copy = _session_ai_history(ai_history_copy, _DASHBOARD_HISTORY_MAX)
        snapshot["ai_history"] = ai_history_copy
        snapshot["ai_history_total"] = ai_history_total
        snapshot["expired_orders_total"] = expired_orders_total
        snapshot["dashboard_history_limit"] = _DASHBOARD_HISTORY_MAX
        snapshot["last_ai_best"] = _pick_dashboard_last_ai(snapshot, ai_history_copy)
        snapshot["deepseek_key_present"] = bool(_deepseek_api_key())
        snapshot["bot_pid"] = os.getpid()
        snapshot["bot_cwd"] = os.getcwd()
        snapshot["bot_script"] = os.path.abspath(__file__)
        snapshot["weak_setup_min_edge"] = get_weak_setup_min_edge()
        snapshot["ai_cooldown_sec"] = get_effective_ai_cooldown_sec()
        snapshot["ai_cooldown_remaining_sec"] = ai_cooldown_remaining_sec()
        snapshot["profit_gates_lane_enabled"] = profit_gates_lane_enabled()
        snapshot["profit_gates_enforced"] = profit_gates_enforced()
        snapshot["research_lane_enabled"] = research_lane_enabled_map()
        snapshot["pathway_lane_status"] = dict(PATHWAY_LANE_STATUS)
        snapshot["research_lane_labels"] = dict(RESEARCH_LANE_LABELS)
        snapshot["research_lanes_independent"] = research_lanes_independent()
        snapshot["pipeline_funnel_counters"] = copy.deepcopy(snapshot.get("pipeline_funnel_counters") or {})
        snapshot["research_isolation_mode"] = research_isolation_enabled()
        snapshot["lane_opportunity_counters"] = copy.deepcopy(snapshot.get("lane_opportunity_counters") or {})
        snapshot["lane_pnl_ledger"] = get_lane_pnl_ledger()
        snapshot["retired_lane_archive"] = get_retired_lane_archive_rows()
        snapshot["lane_position_counts"] = lane_position_counts
        snapshot["research_execution_mode"] = (
            "INDEPENDENT_LANES" if is_research_data_collection() else "LIVE"
        )
        snapshot["dashboard_port"] = DASHBOARD_PORT
        snapshot["dashboard_url"] = dashboard_public_url()
        snapshot["sim_realism"] = {
            "bbo": True,
            "book_depth_vwap": True,
            "executable_marks": True,
            "fee_profile": EXCHANGE_FEE_PROFILE,
            "funding_sim": FUNDING_SIMULATION_ENABLED,
            "book_ts": snapshot.get("book_ts"),
            "bid_size_btc": snapshot.get("bid_size_btc"),
            "ask_size_btc": snapshot.get("ask_size_btc"),
            "deriv_mark_price": (snapshot.get("funding") or {}).get("mark_price"),
        }
        snapshot["positions"] = []
        # Dedupe by trade_id: a position must never appear twice. If the fill path
        # double-appended an identical trade_id, render it once (real exposure = 1x)
        # and warn so the underlying open_positions double-entry stays visible.
        _seen_pos_ids = set()
        _deduped_positions = []
        for _p in positions_copy:
            _tid = _p.get("trade_id")
            if _tid and _tid in _seen_pos_ids:
                logger.warning(f"/api_state duplicate position suppressed trade_id={_tid} (open_positions double-entry - investigate fill path)")
                continue
            if _tid:
                _seen_pos_ids.add(_tid)
            _deduped_positions.append(_p)
        positions_copy = _deduped_positions
        total_unreal = 0.0
        funding_snap = snapshot.get("funding") or {}
        for pos in positions_copy:
            pos_copy = copy.deepcopy(pos)
            mark = get_executable_mark_price(pos, fallback=snapshot.get("price"))
            pos_copy["current_price"] = mark
            pos_copy["mark_side"] = "depth_vwap" if float(pos.get("qty") or 0) > 0 else ("bid" if pos.get("dir") == "LONG" else "ask")
            dir_factor = 1 if pos["dir"] == "LONG" else -1
            move_pct = ((mark - pos["entry"]) / pos["entry"] * 100 * dir_factor) if mark and pos["entry"] else 0
            pnl_usd = (move_pct / 100) * FIXED_MARGIN_USDT * pos.get("leverage", 20)
            pnl_pct_margin = move_pct * pos.get("leverage", 20)
            funding_acc = round(float(pos.get("funding_fees", 0.0) or 0.0), 4)
            pos_copy["pnl_pct_margin"] = pnl_pct_margin
            pos_copy["unreal_usd_gross"] = pnl_usd
            pos_copy["funding_fees_accrued"] = funding_acc
            pos_copy["unreal_usd"] = round(pnl_usd - funding_acc, 4)
            pos_copy["funding_projected_to_settlement"] = round(
                projected_funding_to_next_settlement(pos, funding_snap), 4
            )
            pos_copy["funding_side"] = funding_side_label(
                float(funding_snap.get("rate") or 0.0), pos.get("dir", "LONG")
            )
            total_unreal += pos_copy["unreal_usd"]
            pos_copy["side"] = "LONG" if pos["dir"] == "LONG" else "SHORT"
            pos_copy["leg"] = "Main"
            snapshot["positions"].append(pos_copy)
        snapshot["equity"] = snapshot["account_balance"] + total_unreal
        orders = []
        tick_px = snapshot.get("price")
        for o in pending_orders_copy:
            age = (time.time() - o["created_ts"]) / 60 if o["created_ts"] else 0
            oc = copy.deepcopy(o)
            oc["age_min"] = age
            if tick_px and tick_px > 0:
                oc["limit_touched"] = _pending_limit_touched(o, float(tick_px))
            orders.append(oc)
        snapshot["orders"] = orders
        snapshot["trades"] = trades_copy
        snapshot["expired_orders"] = expired_orders_copy
        snapshot["ai_history"] = ai_history_copy
        snapshot["ai_verdict"] = _ai_execution_verdict_text()
        snapshot["ai_execution_bands"] = get_ai_execution_bands()
        snapshot["chase_execution_buckets"] = get_chase_execution_buckets()
        snapshot["dashboard_execution_gates"] = get_dashboard_execution_status()
        snapshot["chase_analytics"] = _load_chase_analytics_snapshot()
        snapshot["spread_analytics"] = _load_spread_analytics_snapshot()
        snapshot.setdefault("regime", "UNKNOWN")
        snapshot.setdefault("strategy", "SR")
        snapshot.setdefault("direction", "FLAT")
        snapshot.setdefault("ema_status", {})
        snapshot.setdefault("support_resistance", {"pivot": None, "s1": None, "s2": None, "r1": None, "r2": None, "swing_high": None, "swing_low": None, "ts": None, "window": "96x15m (~24h rolling)", "dist_to_resistance": 0.0, "dist_to_support": 0.0, "sr_zone_pct": SR_ZONE_PCT, "sr_state": "UNKNOWN", "sr_bias": "BOTH_ALLOWED"})
        snapshot.setdefault("signal_info", {"active": False, "count": 0, "signals": []})
        snapshot.setdefault("heartbeat", 0)
        snapshot.setdefault("price_ts", 0)
        snapshot["server_ts"] = utc_iso()
        price_ts = snapshot.get("price_ts") or snapshot.get("ws_last_tick") or 0
        snapshot["price_age"] = (now_ts - price_ts) if price_ts else None
        snapshot["ws_age"] = snapshot["price_age"]
        if snapshot.get("price") is None:
            snapshot["price"] = None
        sync_cooldown_debug_state()
        branding = build_dashboard_display(snapshot)
        snapshot.update(branding)
        with state_lock:
            state.update(branding)
        snapshot["signal_info"] = {
            "active": len(active_list) > 0,
            "count": get_active_signal_count(),
            "max": get_effective_max_active_signals(),
            "signals": active_list,
        }
        _enrich_orders_for_relay(snapshot)
        snapshot["trades_map"] = _relay_trades_map_lite()
        snapshot.setdefault("diag", {})
        snapshot["diag"]["signals_last_hour"] = 0
        snapshot["account_balance"] = get_display_balance()
        snapshot["equity"] = snapshot["account_balance"] + total_unreal
        session_trades = trades_copy
        snapshot["trade_count_session"] = _session_trade_count()
        snapshot["trades_display_limit"] = _DASHBOARD_TRADES_MAX
        snapshot["trades"] = [_slim_trade_for_dashboard(t) for t in session_trades]
        snapshot["bot_start_time"] = bot_start_time
        snapshot["fresh_collection_mode"] = bool(state.get("fresh_collection_mode", False))
        snapshot["ai_input"] = LAST_AI_PAYLOAD if LAST_AI_PAYLOAD else state.get("feature_snapshot", {"status": "NO_AI_CALL_YET"})
        snapshot["ai_input_time"] = LAST_AI_TIMESTAMP
        snapshot["feature_snapshot"] = state.get("feature_snapshot", {})
        snapshot["data_quality"] = state.get("data_quality", 0.0)
        snapshot["edge_threshold"] = get_edge_threshold()
        snapshot["edge_threshold_max"] = get_edge_threshold_max()
        snapshot["edge_range_preset"] = state.get("edge_range_preset", DEFAULT_EDGE_RANGE_PRESET)
        snapshot["edge_threshold_display"] = _edge_range_label()
        snapshot["effective_threshold"] = get_effective_edge_threshold()
        snapshot["research_data_collection"] = is_research_data_collection()
        snapshot["edge_options"] = EDGE_OPTIONS
        snapshot["edge_range_presets"] = EDGE_RANGE_PRESETS
        snapshot["max_active_signals"] = state.get("max_active_signals", MAX_CONCURRENT_POSITIONS_DEFAULT)
        snapshot["max_longs"] = MAX_LONGS
        snapshot["max_shorts"] = MAX_SHORTS
        snapshot["last_direction_cap_block"] = state.get("last_direction_cap_block")
        m_fee, t_fee = get_trading_fee_rates()
        snapshot["fee_profile"] = EXCHANGE_FEE_PROFILE
        snapshot["maker_fee_pct"] = m_fee
        snapshot["taker_fee_pct"] = t_fee
        snapshot["funding_simulation_enabled"] = FUNDING_SIMULATION_ENABLED
        snapshot["bot_version"] = EXECUTION_FIX_VERSION
        snapshot["analyzer_sync_id"] = ANALYZER_SYNC_ID
        snapshot["research_kpis"] = get_research_kpis_cached(for_api=True)
        snapshot["pathway_scorecard"] = get_pathway_scorecard_cached(for_api=True)
        snapshot["pathway_lane_specs"] = get_pathway_lane_specs_cached()
        snapshot["continuous_ai_direct_entry_enabled"] = continuous_ai_direct_entry_enabled()
        snapshot["golden_stack_config"] = golden_stack_config_for_dashboard()
        snapshot["duplicate_limit_block_enabled"] = duplicate_limit_block_enabled()
        snapshot["min_signal_age_enabled"] = min_signal_age_enabled()
        snapshot["min_signal_age_sec"] = get_min_signal_age_sec()
        snapshot["smart_submit_enabled"] = smart_submit_enabled()
        snapshot["research_config"] = research_config_for_dashboard()
        with state_lock:
            snapshot["last_replay_model_eval"] = copy.deepcopy(state.get("last_replay_model_eval"))
            snapshot["funding"] = copy.deepcopy(state.get("funding") or {})
        snapshot["display_timezone"] = "Australia/Melbourne"
        snapshot["server_ts_melbourne"] = _format_melbourne_hm(snapshot.get("server_ts") or utc_iso())
        snapshot["ai_input_time_melbourne"] = (
            _format_melbourne_hm(LAST_AI_TIMESTAMP) if LAST_AI_TIMESTAMP else "-"
        )
        session_meta = _load_research_session_meta()
        if session_meta.get("fresh_collection_start_time"):
            snapshot["fresh_collection_start_melbourne"] = _timestamp_to_melbourne_display(
                session_meta["fresh_collection_start_time"]
            )
        fund_out = snapshot.get("funding") or {}
        if fund_out.get("next_time"):
            fund_out["next_time_melbourne"] = _timestamp_to_melbourne_display(fund_out["next_time"])
        elif fund_out.get("next_time_iso"):
            fund_out["next_time_melbourne"] = _format_melbourne_hm(fund_out["next_time_iso"])
        snapshot["funding"] = fund_out
        logger.info(
            f"[API STATE] edge_threshold synced to UI: {snapshot['edge_threshold']} "
            f"elapsed_ms={int((time.perf_counter() - t0) * 1000)} [PIPELINE ENFORCEMENT]"
        )
        with _api_state_cache_lock:
            _api_state_cache["payload"] = snapshot
            _api_state_cache["built_at"] = time.time()
        snapshot["state_integrity"] = build_state_integrity()
        resp = jsonify(snapshot)
        resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
        resp.headers["Pragma"] = "no-cache"
        resp.headers["X-Api-State-Cache"] = "miss"
        return resp
    except Exception as e:
        logger.error(f"/api/state error: {str(e)}")
        err_payload = {
            "api_state_error": str(e)[:500],
            "bot_version": EXECUTION_FIX_VERSION,
            "analyzer_sync_id": ANALYZER_SYNC_ID,
            "bot_pid": os.getpid(),
            "bot_cwd": os.getcwd(),
            "dashboard_port": DASHBOARD_PORT,
            "dashboard_url": dashboard_public_url(),
            "deepseek_key_present": bool(_deepseek_api_key()),
            "research_lane_enabled": research_lane_enabled_map(),
            "continuous_ai_research_enabled": continuous_ai_research_enabled(),
        }
        resp = jsonify(err_payload)
        resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
        return resp, 500
    finally:
        with _api_state_cache_lock:
            _api_state_cache["building"] = False


